update public.products set name = 'Pure NMN 500mg - Anti-Aging', description = 'A direct precursor of NAD+, formulated for maximum intracellular absorption. It supports DNA repair and raises cellular energy levels.', rich_content = '{"faq":[{"answer":"For the best results we recommend taking 1-2 NMN capsules in the morning, on an empty stomach, with a glass of water. NMN is an energizing molecule, which is why it is not advisable to take it late in the evening, as it may affect the quality of your sleep.","question":"When and how should NMN be taken?"},{"answer":"Most users report a rise in energy levels and better mental clarity within the first 7-10 days of consistent use. The deeper anti-aging effects at the cellular level build up after 2-3 months of regular use.","question":"How soon will I see the first results?"},{"answer":"No. Our formula is synthesized through an advanced enzymatic process and is heat-stabilized. The product can be kept at room temperature, in a dry place away from direct sunlight, and will retain its purity of >99%.","question":"Does your NMN need to be kept refrigerated?"}],"reviews":[{"date":"12 June 2026","author":"Michael V.","rating":5,"comment":"I started taking it 3 weeks ago. The most obvious effect is that I no longer get that energy crash at 3pm. I feel much more alert at the office and I seem to recover faster after the gym."},{"date":"03 May 2026","author":"Elena D.","rating":5,"comment":"I take NMN together with resveratrol and the results are excellent. The capsules have no unpleasant taste and go down easily. I really appreciate that you provide the certificate of purity analysis!"},{"date":"18 April 2026","author":"Robert S.","rating":4,"comment":"A very good, high quality product. The only downside is that delivery was one day late on a single occasion, but otherwise the product does exactly what it promises: clean energy all day long."}],"banner_text":"Rebuild your energy reserves at the cellular level with the longevity molecule!","content_image":"/longevitate3.png","why_recommend":["Independently tested purity > 99%","A heat-stabilized formula, with no need for refrigeration","Maximum absorption thanks to the gastro-resistant capsules","Contains no heavy metals, gluten or GMOs"],"ingredients_table":[{"vnr":"**","name":"B-Nicotinamide Mononucleotide (NMN)","quantity":"500 mg"},{"vnr":"**","name":"Black Pepper Extract (BioPerine)","quantity":"5 mg"},{"vnr":"**","name":"Vegetable capsule (HPMC)","quantity":"120 mg"},{"vnr":"**","name":"Organic rice flour (bulking agent)","quantity":"45 mg"},{"vnr":"**","name":"L-Leucine (natural lubricant)","quantity":"10 mg"}],"intro_description":"<p><strong>NMN (Nicotinamide Mononucleotide)</strong> is the molecule that revolutionized the anti-aging field. It works as a direct precursor of NAD+ (Nicotinamide Adenine Dinucleotide), a vital coenzyme present in every cell of the body.</p><p>As we age, NAD+ levels fall dramatically, which leads to fatigue, cognitive decline and a slower metabolism. By supplementing daily with NMN of 99% purity, you support cellular repair and energy from the inside out.</p>"}'::jsonb, tags = ARRAY['Bestseller']::text[] where id = 'af2c0aa0-9a25-4e8b-a003-70876b266cc7';
