update public.products set name = 'Rhodiola Rosea Extract', description = 'The endurance herb of the Vikings. It increases resistance to mental and physical stress, reducing accumulated fatigue.', rich_content = '{"faq":[{"answer":"No. The mental clarity comes purely from the natural nootropic compounds in the mushrooms, so you will not experience jitteriness or a racing heart.","question":"Does it contain caffeine?"},{"answer":"The functional extracts are adaptogenic and help regulate the nervous system. Even so, we recommend taking them in the first half of the day.","question":"Will it affect my sleep?"}],"reviews":[{"date":"08 August 2026","author":"George I.","rating":5,"comment":"I replaced my second coffee of the day with this extract. Incredible focus - I can spend 4 hours glued to the monitor without losing concentration."},{"date":"17 July 2026","author":"Diana M.","rating":5,"comment":"Very good for students during exams! I recommend it 100%."}],"banner_text":"Top mental clarity, steady energy and zero brain fog!","content_image":"/claritate3.png","why_recommend":["100% fruiting body extract (no grain-grown mycelium)","Dual extraction to maximize the active compounds","An adaptogenic effect: it calms and focuses you at the same time"],"ingredients_table":[{"vnr":"**","name":"Concentrated extract (dual extract 10:1)","quantity":"1000 mg"},{"vnr":"**","name":"Active beta-glucans","quantity":"300 mg"},{"vnr":"**","name":"V-Caps® capsule","quantity":"100 mg"},{"vnr":"**","name":"Bamboo extract (source of silicon)","quantity":"25 mg"},{"vnr":"**","name":"Organic rice powder","quantity":"30 mg"}],"intro_description":"<p>Enjoy deep concentration, a sharp memory and mental clarity without the energy crashes that come with caffeine. Our standardized extracts from functional mushrooms and adaptogens are superfoods for your brain.</p><p>It supports neurogenesis (the formation of new neurons) and clears away the “brain fog” even on the busiest and most stressful working days.</p>"}'::jsonb, tags = ARRAY['New Product']::text[] where id = '93728854-2bd9-401f-8f91-1d1330af3431';
update public.products set name = 'Collagen Peptides + Hyaluronic Acid', description = 'The ultimate formula for skin and joints. Collagen peptides restore the elasticity of tissues and hydrate the structure of the dermis.', rich_content = '{"faq":[{"answer":"We recommend 1-2 capsules a day, in the morning with a glass of water, to maximize the rate of cellular absorption throughout the day.","question":"What is the recommended dose?"},{"answer":"The rise in energy is felt within 7-14 days, but deep cellular repair calls for a course of at least 3 months for the best results.","question":"How soon will I see the anti-aging effects?"},{"answer":"Yes. The active substances are 100% bio-identical to the molecules the human body already produces, making them completely safe and non-toxic.","question":"Is it safe to take long term?"}],"reviews":[{"date":"10 July 2026","author":"Victor M.","rating":5,"comment":"I have been using it for 2 months and I have noticed a dramatic improvement in my stamina. I do not tire as quickly any more."},{"date":"22 June 2026","author":"Simone T.","rating":5,"comment":"My blood tests have improved since I started using your longevity products. Happy to recommend them!"},{"date":"05 May 2026","author":"Andrew G.","rating":4,"comment":"A very good supplement. The price is fair for the quality you get."}],"banner_text":"Activate cellular renewal and live at your full potential!","content_image":"/images/premium_bottle_2-removebg-preview.png","why_recommend":["Independently tested purity > 99%","A stabilized formula for maximum bioavailability","No adverse effects, safe for daily use","Fights oxidative stress from the very first dose"],"ingredients_table":[{"vnr":"**","name":"Purified extract (99%)","quantity":"400 mg"},{"vnr":"**","name":"Liposomal absorption complex","quantity":"50 mg"},{"vnr":"**","name":"Vegetable capsule (HPMC)","quantity":"110 mg"},{"vnr":"**","name":"Microcrystalline cellulose","quantity":"30 mg"},{"vnr":"**","name":"Vegetable magnesium stearate","quantity":"5 mg"}],"intro_description":"<p>A state-of-the-art formula designed to slow down cellular aging. Acting directly at the level of the mitochondria, this supplement stimulates longevity and vitality from the inside out.</p><p>By activating the natural process of autophagy (the clearing of senescent cells), your body regains the energy and the capacity for regeneration of its younger years.</p>"}'::jsonb, tags = ARRAY['For Women']::text[] where id = '7befa0fc-f3b9-4dac-849f-ee69de15b96c';
update public.products set name = 'Quercetin with Bromelain', description = 'A natural anti-inflammatory complex. Quercetin modulates the histamine response, while bromelain amplifies its absorption.', rich_content = '{"faq":[{"answer":"Although our extracts are very gentle on the stomach lining, we recommend taking it after a meal (ideally one containing a little healthy fat).","question":"Can it be taken on an empty stomach?"},{"answer":"Yes. This product belongs to the Essentials category, so the body needs it consistently in order to prevent deficiencies.","question":"Can I use the product all year round?"}],"reviews":[{"date":"14 August 2026","author":"Camilla P.","rating":5,"comment":"I have felt great since I started taking it, and the biggest plus is that it causes me no nausea at all, which used to happen with other brands."},{"date":"29 July 2026","author":"Florian B.","rating":5,"comment":"My blood work came back perfect! Exactly what I was looking for."}],"banner_text":"The foundation of iron-clad health, every single day!","content_image":"/images/premium_bottle_10-removebg-preview.png","why_recommend":["A bio-identical molecular form for perfect absorption","Free of heavy metals and toxins","Needed daily for your body to work at its best"],"ingredients_table":[{"vnr":"100%","name":"Premium active substance","quantity":"1000 mg"},{"vnr":"**","name":"Absorption cofactors","quantity":"25 mg"},{"vnr":"**","name":"Dicalcium phosphate","quantity":"40 mg"},{"vnr":"**","name":"Enteric coating","quantity":"15 mg"},{"vnr":"**","name":"Silicon dioxide","quantity":"2 mg"}],"intro_description":"<p>The foundation of your daily health. Our bodies cannot efficiently synthesize certain micro-elements, which is why a clean and highly absorbable supplement makes all the difference.</p><p>Whether it is immune support, cardiovascular protection or bone health, this staple product has been formulated using only the highest quality and safest raw materials.</p>"}'::jsonb, tags = '{}'::text[] where id = 'cdf1cd23-36e5-4f74-bcdd-7bce788b7f09';
