update public.products set name = 'The Anti-Aging Protocol (NMN+Resveratrol)', description = 'Known as the "Sinclair Protocol", it acts on the causes of aging at the molecular level.', rich_content = '{"faq":[{"answer":"The products can be taken alongside one another (on the same day). As a rule, you will find the specific instructions on the label of each bottle in the bundle.","question":"How do I take the products in the bundle?"},{"answer":"Yes. This bundle is built to be the foundation of your health and can safely be combined with most vitamins.","question":"Can it be combined with other supplements?"}],"reviews":[{"date":"02 August 2026","author":"Anna C.","rating":5,"comment":"It works out much cheaper buying the bundle, and the results are wonderful! Delivery was next day."},{"date":"25 July 2026","author":"Martin D.","rating":4,"comment":"Top products, combined excellently."}],"banner_text":"Complete synergy for fast results. Plus savings when you buy the bundle!","content_image":"/7.png","why_recommend":["A complete formula designed by specialists","A proven synergistic effect (1+1=3)","Great value when the products are bought together"],"ingredients_table":[{"vnr":"**","name":"Main product (base)","quantity":"1 bottle (60 caps)"},{"vnr":"**","name":"Secondary product (synergistic)","quantity":"1 bottle (60 caps)"},{"vnr":"**","name":"Digital usage guide","quantity":"1 pc"},{"vnr":"**","name":"Premium gift packaging","quantity":"Included"},{"vnr":"**","name":"Fast priority shipping","quantity":"Free"}],"intro_description":"<p>The perfect synergy for maximum results. We built this bundle by combining our most complementary products, so that a specific problem is tackled from several angles at once.</p><p>When ingredients work together, their effect does not add up - it multiplies. Enjoy optimal health and save by buying the bundle.</p>"}'::jsonb, tags = ARRAY['Great Price', '-15%']::text[] where id = '4b94306d-5832-4407-8881-4c8ab446f3c6';
