update public.products set name = 'Magnesium Bisglycinate', description = 'The most absorbable and gentlest form of magnesium (it causes no stomach discomfort). It fights stress, relaxes the muscles and dramatically improves sleep quality.', rich_content = '{"faq":[{"answer":"Thanks to its bisglycinate form it is very gentle on the stomach and can be taken on an empty stomach without trouble, although we recommend the evening, after a light meal.","question":"Can it be taken on an empty stomach?"},{"answer":"No. Unlike magnesium oxide or citrate, bisglycinate is absorbed directly and does not draw water into the intestines, so it has no laxative effect at all.","question":"Does it have a laxative effect?"}],"reviews":[{"date":"14 August 2026","author":"Andrea M.","rating":5,"comment":"I sleep far more deeply since I started taking it. I wake up rested and I no longer get muscle cramps at all."},{"date":"29 July 2026","author":"Florian B.","rating":5,"comment":"The best magnesium I have tried. My stomach is very sensitive but I have had no trouble at all with this one."}],"banner_text":"Deep sleep, relaxed muscles and a balanced nervous system","content_image":"/images/premium_bottle_3-removebg-preview.png","why_recommend":["Far better absorption than magnesium oxide or citrate","Gentle on the stomach, with zero digestive discomfort","Synergy with bioactive vitamin B6 for muscle relaxation"],"ingredients_table":[{"vnr":"53%","name":"Elemental magnesium (from bisglycinate)","quantity":"200 mg"},{"vnr":"142%","name":"Vitamin B6 (pyridoxal-5-phosphate)","quantity":"2 mg"},{"vnr":"**","name":"Free L-glycine","quantity":"100 mg"},{"vnr":"-","name":"Vegetable capsule (HPMC)","quantity":"-"},{"vnr":"-","name":"Organic rice flour","quantity":"-"}],"intro_description":"<p>The ultimate form of magnesium for calming the nervous system. Magnesium Bisglycinate is created by binding magnesium to two molecules of the amino acid glycine, which gives excellent intestinal absorption <strong>with no laxative effect</strong>.</p><p>Ideal taken in the evening before bed, this supplement reduces the stress built up over the day and prepares the body for deep, restorative sleep.</p>"}'::jsonb, tags = ARRAY['Great Price']::text[] where id = '0b5a2b3e-9b7e-48df-96bf-eede56b9dbbb';
